B.aZl=new A.a("\u0641\u0628\u064a\u0646\u0645\u0627 \u0623\u0646\u0627 \u062c\u0627\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644 \u0627\u0644\u062a\u064a \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0645\u0646\u0627\u060c \u0642\u062f \u0636\u0627\u0642\u062a \u0639\u0644\u064a\u0651\u064e \u0646\u0641\u0633\u064a \u0648\u0636\u0627\u0642\u062a \u0639\u0644\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0645\u0627 \u0631\u062d\u0628\u062a\u060c \u0633\u0645\u0639\u062a \u0635\u0648\u062a \u0635\u0627\u0631\u062e \u0623\u0648\u0641\u064a\u0649 \u0639\u0644\u0649 \u0633\u0644\u0639 -\u0635\u0639\u062f\u0647 \u0648\u0627\u0631\u062a\u0641\u0639 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0639 \u062c\u0628\u0644 \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629- \u064a\u0642\u0648\u0644 \u0628\u0623\u0639\u0644\u0649 \u0635\u0648\u062a\u0647: \u064a\u0627\u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0623\u0628\u0634\u0631\u060c \u0642\u0627\u0644: \u0641\u062e\u0631\u0631\u062a \u0633\u0627\u062c\u062f\u0627\u064b \u0648\u0639\u0631\u0641\u062a \u0623\u0646 \u0642\u062f \u062c\u0627\u0621 \u0641\u0631\u062c \u0642\u0627\u0644: \u0641\u0622\u0630\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062a\u0648\u0628\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0646\u0627 \u062d\u064a\u0646 \u0635\u0644\u0649 \u0635\u0644\u0627\u0629 \u0627\u0644\u0641\u062c\u0631 \u0641\u0630\u0647\u0628 \u0627\u0644\u0646\u0627\u0633 \u064a\u0628\u0634\u0631\u0648\u0646\u0646\u0627 \u0641\u0630\u0647\u0628 \u0642\u0650\u0628\u064e\u0644 \u0635\u0627\u062d\u0628\u064a \u0645\u0628\u0634\u0631\u0648\u0646 \u0648\u0631\u0643\u0636 \u0631\u062c\u0644 \u0625\u0644\u064a\u0651\u064e \u0641\u0631\u0633\u0627\u064b \u0648\u0633\u0639\u0649 \u0633\u0627\u0639 \u0645\u0646 \u0623\u0633\u0644\u0645 \u0642\u0628\u0644\u064a\u060c \u0648\u0623\u0648\u0641\u0649 \u0627\u0644\u062c\u0628\u0644 \u0641\u0643\u0627\u0646 \u0627\u0644\u0635\u0648\u062a \u0623\u0633\u0631\u0639 \u0645\u0646 \u0627\u0644\u0641\u0631\u0633\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621\u0646\u064a \u0627\u0644\u0630\u064a \u0633\u0645\u0639\u062a \u0635\u0648\u062a\u0647 \u064a\u0628\u0634\u0631\u0646\u064a \u0641\u0646\u0632\u0639\u062a \u0644\u0647 \u062b\u0648\u0628\u064a\u0651 \u0641\u0643\u0633\u0648\u062a\u0647\u0645\u0627 \u0625\u064a\u0627\u0647 \u0628\u0628\u0634\u0627\u0631\u062a\u0647 \u0648\u0627\u0644\u0644\u0647! \u0645\u0627 \u0623\u0645\u0644\u0643 \u063a\u064a\u0631\u0647\u0645\u0627 \u064a\u0648\u0645\u0626\u0630\u060c \u0648\u0627\u0633\u062a\u0639\u0631\u062a \u062b\u0648\u0628\u064a\u0646 \u0641\u0644\u0628\u0633\u062a\u0647\u0645\u0627 \u0641\u0627\u0646\u0637\u0644\u0642\u062a \u0623\u062a\u0623\u0645\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u064a\u062a\u0644\u0642\u0646\u064a \u0627\u0644\u0646\u0627\u0633 \u0641\u0648\u062c\u0627 \u0641\u0648\u062c\u0627 \u064a\u0647\u0646\u0626\u0648\u0646\u064a \u0628\u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0644\u062a\u0647\u0646\u0626\u0643 \u062a\u0648\u0628\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u060c \u062d\u062a\u0649 \u062f\u062e\u0644\u062a \u0627\u0644\u0645\u0633\u062c\u062f \u0641\u0625\u0630\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062c\u0627\u0644\u0633 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0648\u062d\u0648\u0644\u0647 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0642\u0627\u0645 \u0637\u0644\u062d\u0629 \u0628\u0646 \u0639\u0628\u064a\u062f \u0627\u0644\u0644\u0647 \u064a\u0647\u0631\u0648\u0644 \u062d\u062a\u0649 \u0635\u0627\u0641\u062d\u0646\u064a \u0648\u0647\u0646\u0623\u0646\u064a \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0642\u0627\u0645 \u0631\u062c\u0644 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u063a\u064a\u0631\u0647\u060c \u0642\u0627\u0644: \u0641\u0643\u0627\u0646 \u0643\u0639\u0628 \u0644\u0627\u064a\u0646\u0633\u0627\u0647\u0627 \u0644\u0637\u0644\u062d\u0629.",null)
B.awA=new A.a("\u0642\u0627\u0644 \u0643\u0639\u0628: \u0641\u0644\u0645\u0627 \u0633\u0644\u0645\u062a \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0627\u0644: \u0648\u0647\u0648 \u064a\u0628\u0631\u0642 \u0648\u062c\u0647\u0647 \u0645\u0646 \u0627\u0644\u0633\u0631\u0648\u0631 \u0648\u064a\u0642\u0648\u0644: \u0623\u0628\u0634\u0631 \u0628\u062e\u064a\u0631 \u064a\u0648\u0645 \u0645\u0631 \u0639\u0644\u064a\u0643 \u0645\u0646\u0630 \u0648\u0644\u062f\u062a\u0643 \u0623\u0645\u0643\u060c \u0642\u0627\u0644: \u0642\u0644\u062a: \u0623\u0645\u0646 \u0639\u0646\u062f\u0643\u061f \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0645 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u061f \u0641\u0642\u0627\u0644: \u0644\u0627\u0628\u0644 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0630\u0627 \u0627\u0633\u062a\u0646\u0627\u0631 \u0648\u062c\u0647\u0647 \u0643\u0627\u0646 \u0642\u0637\u0639\u0629 \u0642\u0645\u0631 \u060c \u0642\u0627\u0644: \u0648\u0643\u0646\u0627 \u0646\u0639\u0631\u0641 \u0630\u0644\u0643 \u060c \u0648\u0642\u0627\u0644: \u0641\u0644\u0645\u0627 \u062c\u0644\u0633\u062a \u0628\u064a\u0646 \u064a\u062f\u064a\u0647 \u0642\u0644\u062a \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647: \u0625\u0646 \u0645\u0646 \u062a\u0648\u0628\u062a\u064a \u0623\u0646 \u0623\u0646\u062e\u0644\u0639 \u0645\u0646 \u0645\u0627\u0644\u064a \u0635\u062f\u0642\u0629 -\u0623\u062a\u0635\u062f\u0642 \u0628\u0647- \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0625\u0644\u0649 \u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u0645\u0633\u0643 \u0628\u0639\u0636 \u0645\u0627\u0644\u0643 \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643 \u0642\u0627\u0644: \u0641\u0642\u0644\u062a: \u0641\u0625\u0646\u064a \u0623\u0645\u0633\u0643 \u0633\u0647\u0645\u064a \u0627\u0644\u0630\u064a \u0628\u062e\u064a\u0628\u0631\u060c \u0642\u0627\u0644: \u0648\u0642\u0644\u062a: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0625\u0646\u0645\u0627 \u0623\u0646\u062c\u0627\u0646\u064a \u0628\u0627\u0644\u0635\u062f\u0642 \u0648\u0625\u0646 \u0645\u0646 \u062a\u0648\u0628\u062a\u064a \u0623\u0646 \u0644\u0627 \u0623\u062d\u062f\u062b \u0625\u0644\u0627 \u0635\u062f\u0642\u0627\u064b \u0645\u0627\u0628\u0642\u064a\u062a \u0642\u0627\u0644: \u0641\u0648 \u0627\u0644\u0644\u0647 \u0645\u0627\u0639\u0644\u0645\u062a \u0623\u0646 \u0623\u062d\u062f\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0623\u0628\u0644\u0627\u0647 \u0627\u0644\u0644\u0647 -\u0623\u0646\u0639\u0645 \u0639\u0644\u064a\u0647- \u0641\u064a \u0635\u062f\u0642 \u0627\u0644\u062d\u062f\u064a\u062b \u0645\u0646\u0630 \u0630\u0643\u0631\u062a \u0630\u0644\u0643 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u064a\u0648\u0645\u064a \u0647\u0630\u0627 \u0623\u062d\u0633\u0646 \u0645\u0645\u0627 \u0623\u0628\u0644\u0627\u0646\u064a \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u062a\u0639\u0645\u062f\u062a \u0643\u0630\u0628\u0629 \u0645\u0646\u0630 \u0642\u0644\u062a \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u064a\u0648\u0645\u064a \u0647\u0630\u0627 \u0648\u0625\u0646\u064a \u0644\u0623\u0631\u062c\u0648 \u0623\u0646 \u064a\u062d\u0641\u0638\u0646\u064a \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0628\u0642\u0649.",null)
