B.aW8=new A.a("\u0644\u0645 \u062a\u0643\u062a\u0641 \u0642\u064a\u0627\u062f\u0629 \u0642\u0631\u064a\u0634 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u062f\u0627\u062e\u0644 \u0645\u0643\u0629\u060c \u0644\u0645\u0646\u0639\u0647\u0645 \u0645\u0646 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0628\u0644 \u062a\u0639\u062f\u062a \u0630\u0644\u0643 \u0625\u0644\u0649 \u0645\u062d\u0627\u0648\u0644\u0629 \u0625\u0631\u062c\u0627\u0639 \u0645\u0646 \u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0645\u0647\u0627\u062c\u0631\u0627\u064b\u060c \u0641\u0642\u0627\u0645\u062a \u0628\u062a\u0646\u0641\u064a\u0630 \u0639\u0645\u0644\u064a\u0629 \u0627\u062e\u062a\u0637\u0627\u0641 \u0623\u062d\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0648\u0644\u0642\u062f \u0646\u062c\u062d\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0648\u062a\u0645 \u0627\u062e\u062a\u0637\u0627\u0641 \u0623\u062d\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0647\u0648 \u0639\u064a\u0627\u0634 \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629 \u0648\u0623\u0639\u064a\u062f \u0625\u0644\u0649 \u0645\u0643\u0629.",null)
B.ax9=new A.a("\u0641\u0642\u062f \u0648\u0636\u0639 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062e\u0637\u0629 \u0644\u0644\u0647\u062c\u0631\u0629 \u0644\u0647\u060c \u0648\u0644\u0635\u0627\u062d\u0628\u064a\u0647 \u0639\u064a\u0627\u0634 \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629 \u0648\u0647\u0634\u0627\u0645 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0627\u0644\u0633\u0647\u0645\u064a\u060c \u0648\u0643\u0627\u0646 \u062b\u0644\u0627\u062b\u062a\u0647\u0645 \u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646 \u0642\u0628\u064a\u0644\u0629\u060c \u0648\u0643\u0627\u0646 \u0645\u0643\u0627\u0646 \u0627\u0644\u0642\u0627\u0621 \u0639\u0646\u062f \u0627\u0644\u062a\u0646\u0627\u0636\u0628 -\u062c\u0645\u0639 \u062a\u0646\u0636\u064a\u0628 \u0648\u0647\u0648 \u0634\u062c\u0631 \u0645\u0646 \u0623\u0636\u0627\u0629-\u0639\u0644\u0649 \u0628\u064f\u0639\u062f \u0639\u0634\u0631\u0629 \u0623\u0645\u064a\u0627\u0644 \u0639\u0646 \u0645\u0643\u0629\u060c \u0648\u0625\u0630\u0627 \u062a\u062e\u0644\u0641 \u0623\u062d\u062f\u0647\u0645 \u0641\u0644\u064a\u0645\u0636 \u0635\u0627\u062d\u0628\u0627\u0647 \u0648\u0644\u0627 \u064a\u0646\u062a\u0638\u0631\u0627\u0646\u0647\u060c \u0644\u0623\u0646\u0647 \u0642\u062f \u062d\u064f\u0628\u0633\u060c \u0648\u0643\u0645\u0627 \u062a\u0648\u0642\u0639\u0648\u0627 \u0641\u0642\u062f \u062d\u064f\u0628\u0633 \u0647\u0634\u0627\u0645 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u064a\u0646\u0645\u0627 \u0645\u0636\u0649 \u0639\u0645\u0631 \u0648\u0639\u064a\u0627\u0634 \u0628\u0647\u062c\u0631\u062a\u0647\u0645\u0627.",null)
B.aA4=new A.a("\u0648\u064a\u062d\u062f\u062b\u0646\u0627 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0648\u0644\u0645\u0627 \u0642\u062f\u0645\u0646\u0627 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0646\u0632\u0644\u0646\u0627 \u0641\u064a \u0628\u0646\u064a \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u0648\u0641 \u0628\u0642\u0628\u0627\u0621\u060c \u0648\u062e\u0631\u062c \u0623\u0628\u0648 \u062c\u0647\u0644 \u0628\u0646 \u0647\u0634\u0627\u0645 \u0648\u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0647\u0634\u0627\u0645 \u0625\u0644\u0649 \u0639\u064a\u0627\u0634 \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629\u060c \u0648\u0643\u0627\u0646 \u0627\u0628\u0646 \u0639\u0645\u0647\u0645\u0627 \u0648\u0623\u062e\u0627\u0647\u0627 \u0644\u0623\u0645\u0647\u0645\u0627\u060c \u062d\u062a\u0649 \u0642\u062f\u0645\u0627 \u0639\u0644\u064a\u0646\u0627 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0645\u0643\u0629\u060c \u0641\u0643\u0644\u0645\u0627\u0647\u060c \u0648\u0642\u0627\u0644\u0627: \u0625\u0646 \u0623\u0645\u0643 \u0642\u062f \u0646\u0630\u0631\u062a \u0623\u0646 \u0644\u0627 \u064a\u0645\u0633 \u0631\u0623\u0633\u0647\u0627 \u0645\u0634\u0637 \u062d\u062a\u0649 \u062a\u0631\u0627\u0643\u060c \u0648\u0644\u0627 \u062a\u0633\u062a\u0638\u0644 \u0645\u0646 \u0634\u0645\u0633 \u062d\u062a\u0649 \u062a\u0631\u0627\u0643\u060c \u0641\u0631\u0642 \u0644\u0647\u0627\u060c \u0641\u0642\u0644\u062a \u0644\u0647: \u0639\u064a\u0627\u0651\u0634 \u0625\u0646\u0647 \u0648\u0627\u0644\u0644\u0647 \u0625\u0646 \u064a\u0631\u064a\u062f\u0643 \u0627\u0644\u0642\u0648\u0645 \u0625\u0644\u0627 \u0644\u064a\u0641\u062a\u0646\u0648\u0643 \u0639\u0646 \u062f\u064a\u0646\u0643\u060c \u0641\u0627\u062d\u0630\u0631\u0647\u0645\u060c \u0641\u0648\u0627\u0644\u0644\u0647 \u0644\u0648 \u0642\u062f \u0622\u0630\u0649 \u0623\u0645\u0643 \u0627\u0644\u0642\u0645\u0644 \u0644\u0627\u0645\u062a\u0634\u0637\u062a\u060c \u0648\u0644\u0648 \u0642\u062f \u0627\u0634\u062a\u062f \u0639\u0644\u064a\u0647\u0627 \u062d\u0631 \u0645\u0643\u0629 \u0644\u0627\u0633\u062a\u0638\u0644\u062a.",null)
B.aRK=new A.a("\u0642\u0627\u0644: \u0623\u0628\u0631 \u0642\u0633\u0645 \u0623\u0645\u064a\u060c \u0648\u0644\u064a \u0647\u0646\u0627\u0643 \u0645\u0627\u0644 \u0641\u0622\u062e\u0630\u0647\u060c \u0642\u0627\u0644: \u0641\u0642\u0644\u062a: \u0648\u0627\u0644\u0644\u0647 \u0625\u0646\u0643 \u0644\u062a\u0639\u0644\u0645 \u0623\u0646\u064a \u0644\u0645\u0646 \u0623\u0643\u062b\u0631 \u0642\u0631\u064a\u0634 \u0645\u0627\u0644\u0627\u064b\u060c \u0641\u0644\u0643 \u0646\u0635\u0641 \u0645\u0627\u0644\u064a \u0648\u0644\u0627 \u062a\u0630\u0647\u0628 \u0645\u0639\u0647\u0645\u0627\u060c \u0642\u0627\u0644: \u0641\u0623\u0628\u0649 \u0639\u0644\u064a \u0625\u0644\u0627 \u0623\u0646 \u064a\u062e\u0631\u062c \u0645\u0639\u0647\u0645\u0627\u060c \u0641\u0644\u0645\u0627 \u0623\u0628\u0649 \u0625\u0644\u0627 \u0630\u0644\u0643\u060c \u0642\u0627\u0644: \u0642\u0644\u062a \u0644\u0647: \u0623\u0645\u0627 \u0625\u0630 \u0642\u062f \u0641\u0639\u0644\u062a \u0645\u0627 \u0641\u0639\u0644\u062a\u060c \u0641\u062e\u0630 \u0646\u0627\u0642\u062a\u064a \u0647\u0630\u0647 \u0641\u0625\u0646\u0647\u0627 \u0646\u0627\u0642\u0629 \u0646\u062c\u064a\u0628\u0629 \u0630\u0644\u0648\u0644 -\u0633\u0647\u0644\u0629 \u0627\u0644\u0631\u0643\u0648\u0628- \u0641\u0627\u0644\u0632\u0645 \u0638\u0647\u0631\u0647\u0627\u060c \u0641\u0625\u0646 \u0631\u0627\u0628\u0643 \u0645\u0646 \u0627\u0644\u0642\u0648\u0645 \u0631\u064a\u0628 \u0641\u0627\u0646\u062c \u0639\u0644\u064a\u0647\u0627\u060c \u0641\u062e\u0631\u062c \u0639\u0644\u064a\u0647\u0627 \u0645\u0639\u0647\u0645\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0643\u0627\u0646\u0648\u0627 \u0628\u0628\u0639\u0636 \u0627\u0644\u0637\u0631\u064a\u0642 \u0642\u0627\u0644 \u0644\u0647 \u0623\u0628\u0648 \u062c\u0647\u0644: \u064a\u0627 \u0623\u062e\u064a\u060c \u0648\u0627\u0644\u0644\u0647 \u0644\u0642\u062f \u0627\u0633\u062a\u063a\u0644\u0638\u062a \u0628\u0639\u064a\u0631\u064a \u0647\u0630\u0627\u060c \u0623\u0641\u0644\u0627 \u062a\u0639\u0642\u0628\u0646\u064a \u0647\u0630\u0647 -\u062a\u062c\u0639\u0644\u0646\u064a \u0623\u0639\u0642\u0628\u0643 \u0639\u0644\u064a\u0647\u0627 \u0644\u0631\u0643\u0648\u0628\u0647\u0627 \u0639\u0644\u0649 \u0646\u0627\u0642\u062a\u0643- \u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0642\u0627\u0644: \u0641\u0623\u0646\u0627\u062e\u060c \u0648\u0623\u0646\u0627\u062e\u060c \u0644\u064a\u062a\u062d\u0648\u0644 \u0639\u0644\u064a\u0647\u0627\u060c \u0641\u0644\u0645\u0627 \u0627\u0633\u062a\u0648\u0648\u0627 \u0628\u0627\u0644\u0623\u0631\u0636 \u0639\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u060c \u0641\u0623\u0648\u062b\u0642\u0627\u0647\u060c \u062b\u0645 \u062f\u062e\u0644\u0627 \u0628\u0647 \u0645\u0643\u0629\u060c \u0648\u0641\u062a\u0646\u0627\u0647 \u0641\u0627\u0641\u062a\u062a\u0646.",null)
