B.aB8=new A.a("\u0648\u0639\u0646 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0628\u064a\u0646\u0645\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u0627\u0626\u0645 \u064a\u0635\u0644\u064a \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0648\u062c\u0645\u0639 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0641\u064a \u0645\u062c\u0627\u0644\u0633\u0647\u0645 \u0625\u0630 \u0642\u0627\u0644 \u0642\u0627\u0626\u0644 \u0645\u0646\u0647\u0645: \u0623\u0644\u0627 \u062a\u0646\u0638\u0631\u0648\u0646 \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0645\u0631\u0627\u0626\u064a\u061f \u0623\u064a\u0643\u0645 \u064a\u0642\u0648\u0645 \u0625\u0644\u0649 \u0633\u0644\u0627 \u062c\u064e\u0632\u0648\u0631 -\u0628\u0637\u0646 \u0627\u0644\u0646\u0627\u0642\u0629- \u0628\u0646\u064a \u0641\u0644\u0627\u0646\u060c \u0641\u064a\u0639\u0645\u062f \u0625\u0644\u0649 \u0641\u0631\u062b\u0647\u0627 \u0648\u062f\u0645\u0647\u0627 \u0648\u0633\u064e\u0644\u0627\u0647\u0627\u060c \u0641\u064a\u062c\u064a\u0621 \u0628\u0647 \u062b\u0645 \u064a\u0645\u0647\u0644\u0647 \u062d\u062a\u0649 \u0625\u0630\u0627 \u0633\u062c\u062f \u0648\u0636\u0639\u0647 \u0628\u064a\u0646 \u0643\u062a\u0641\u064a\u0647\u061f \u0641\u0627\u0646\u0628\u0639\u062b \u0623\u0634\u0642\u0627\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0633\u062c\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0636\u0639\u0647 \u0628\u064a\u0646 \u0643\u062a\u0641\u064a\u0647\u060c \u0648\u062b\u0628\u062a \u0627\u0644\u0646\u0628\u064a \ufdfa \u0633\u0627\u062c\u062f\u064b\u0627 \u060c \u0641\u0636\u062d\u0643\u0648\u0627 \u062d\u062a\u0649 \u0645\u0627\u0644 \u0628\u0639\u0636\u0647\u0645 \u0625\u0644\u0649 \u0628\u0639\u0636 \u0645\u0646 \u0627\u0644\u0636\u062d\u0643.",null)
B.aRO=new A.a("\u0641\u0627\u0646\u0637\u0644\u0642 \u0645\u0646\u0637\u0644\u0642 \u0625\u0644\u0649 \u0641\u0627\u0637\u0645\u0629 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0633\u0644\u0627\u0645 -\u0648\u0647\u064a \u062c\u0648\u064a\u0631\u064a\u0629- \u0641\u0623\u0642\u0628\u0644\u062a \u062a\u0633\u0639\u0649\u060c \u0648\u062b\u0628\u062a \u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u062a\u0649 \u0623\u0644\u0642\u062a\u0647 \u0639\u0646\u0647\u060c \u0648\u0623\u0642\u0628\u0644\u062a \u0639\u0644\u064a\u0647\u0645 \u062a\u0633\u0628\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0642\u0636\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0635\u0644\u0627\u0629 \u0642\u0627\u0644: \u0627\u0644\u0644\u0647\u0645 \u0639\u0644\u064a\u0643 \u0628\u0642\u0631\u064a\u0634\u060c \u0627\u0644\u0644\u0647\u0645 \u0639\u0644\u064a\u0643 \u0628\u0642\u0631\u064a\u0634\u060c \u0627\u0644\u0644\u0647\u0645 \u0639\u0644\u064a\u0643 \u0628\u0642\u0631\u064a\u0634\u060c \u062b\u0645 \u0633\u0645\u0651\u0649: \u0627\u0644\u0644\u0647\u0645 \u0639\u0644\u064a\u0643 \u0628\u0639\u0645\u0631\u0648 \u0628\u0646 \u0647\u0634\u0627\u0645\u060c \u0648\u0639\u062a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u0634\u064a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629\u060c \u0648\u0627\u0644\u0648\u0644\u064a\u062f \u0628\u0646 \u0639\u062a\u0628\u0629\u060c \u0648\u0623\u0645\u064a\u0629 \u0628\u0646 \u062e\u0644\u0641 \u0648\u0639\u0642\u0628\u0629 \u0628\u0646 \u0623\u0628\u064a \u0645\u0639\u064a\u0637\u060c \u0648\u0639\u0645\u0627\u0631\u0629 \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f\u060c \u0642\u0627\u0644 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f: \u0641\u0648\u0627\u0644\u0644\u0647 \u0644\u0642\u062f \u0631\u0623\u064a\u062a\u0647\u0645 \u0635\u0631\u0639\u0649 \u064a\u0648\u0645 \u0628\u062f\u0631\u060c \u062b\u0645 \u0633\u062d\u0628\u0648\u0627 \u0625\u0644\u0649 \u0642\u0644\u064a\u0628 \u0628\u062f\u0631 - \u0627\u0644\u0628\u0626\u0631 \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629 \u0641\u0649 \u0628\u062f\u0631 \u060c \u062b\u0645 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0648\u0623\u062a\u0628\u0639 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0642\u0644\u064a\u0628 \u0644\u0639\u0646\u0629.",null)
B.ax3=new A.a("\u0648\u0642\u062f \u0628\u064a\u0646\u062a \u0627\u0644\u0631\u0648\u0627\u064a\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0623\u0646 \u0627\u0644\u0630\u064a \u0631\u0645\u0649 \u0627\u0644\u0641\u0631\u062b \u0639\u0644\u064a\u0647 \u0647\u0648 \u0639\u0642\u0628\u0629 \u0628\u0646 \u0623\u0628\u064a \u0645\u0639\u064a\u0637\u060c \u0648\u0623\u0646 \u0627\u0644\u0630\u064a \u062d\u0631\u0636\u0647 \u0647\u0648 \u0623\u0628\u0648 \u062c\u0647\u0644 \u060c \u0648\u0623\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062a\u0623\u062b\u0631\u0648\u0627 \u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0648\u0634\u0642 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0623\u0645\u0631\u060c \u0644\u0623\u0646\u0647\u0645 \u064a\u0631\u0648\u0646 \u0623\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0628\u0645\u0643\u0629 \u0645\u0633\u062a\u062c\u0627\u0628\u0629.",null)
