B.aZy=new A.a("\u0625\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0627\u0641\u0642 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0639\u0644\u0649 \u062a\u0631\u0643 \u0643\u062a\u0627\u0628\u0629 \u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062d\u0645\u0646 \u0627\u0644\u0631\u062d\u064a\u0645 \u0648\u0643\u062a\u0627\u0628\u0629 \u0628\u0627\u0633\u0645\u0643 \u0627\u0644\u0644\u0647\u0645 \u0628\u062f\u0644\u0627\u064b \u0639\u0646\u0647\u0627\u060c \u0648\u0643\u0630\u0627 \u0648\u0627\u0641\u0642\u0647\u0645 \u0641\u064a \u0643\u062a\u0627\u0628\u0629 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0648\u062a\u0631\u0643 \u0643\u062a\u0627\u0628\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0648\u0643\u0630\u0627 \u0648\u0627\u0641\u0642\u0647\u0645 \u0641\u064a \u0631\u062f\u0651 \u0645\u0646 \u062c\u0627\u0621 \u0645\u0646\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u062f\u0648\u0646 \u0645\u0646 \u0630\u0647\u0628 \u0645\u0646\u0647\u0645 \u0625\u0644\u064a\u0647\u0645\u060c \u0648\u0625\u0646\u0645\u0627 \u0648\u0627\u0641\u0642\u0647\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631 \u0644\u0644\u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0645\u0647\u0645\u0629 \u0627\u0644\u062d\u0627\u0635\u0644\u0629 \u0628\u0627\u0644\u0635\u0644\u062d \u0645\u0639 \u0623\u0646\u0647 \u0644\u0627\u0645\u0641\u0633\u062f\u0629 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0623\u0645\u0627 \u0627\u0644\u0628\u0633\u0645\u0644\u0629 \u0648\u0628\u0627\u0633\u0645\u0643 \u0627\u0644\u0644\u0647\u0645 \u0641\u0645\u0639\u0646\u0627\u0647\u0627 \u0648\u0627\u062d\u062f\u060c \u0648\u0643\u0630\u0627 \u0642\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0647\u0648 \u0623\u064a\u0636\u0627\u064b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0648\u0644\u064a\u0633 \u0641\u064a \u062a\u0631\u0643 \u0648\u0635\u0641 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0636\u0639 \u0628\u0627\u0644\u0631\u062d\u0645\u0646 \u0627\u0644\u0631\u062d\u064a\u0645 \u0645\u0627\u064a\u0646\u0641\u064a \u0630\u0644\u0643\u060c \u0648\u0644\u0627\u0641\u064a \u062a\u0631\u0643 \u0648\u0635\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0645\u0627\u064a\u0646\u0641\u064a\u0647\u0627\u060c \u0641\u0644\u0627 \u0636\u0631\u0631 \u0648\u0644\u0627\u0645\u0641\u0633\u062f\u0629 \u0641\u064a\u0645\u0627 \u0637\u0644\u0628\u0648\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u0643\u0627\u0646\u062a \u0627\u0644\u0645\u0641\u0633\u062f\u0629 \u062a\u0643\u0648\u0646 \u0644\u0648 \u0637\u0644\u0628\u0648\u0627 \u0623\u0646 \u064a\u0643\u062a\u0628 \u0645\u0627\u0644\u0627 \u064a\u062d\u0644 \u0645\u0646 \u062a\u0639\u0638\u064a\u0645 \u0622\u0644\u0647\u062a\u0647\u0645 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643.",null)
B.b_5=new A.a("\u0648\u0623\u0645\u0627 \u0634\u0631\u0637 \u0631\u062f\u0651 \u0645\u0646 \u062c\u0627\u0621 \u0645\u0646\u0647\u0645 \u0648\u0639\u062f\u0645 \u0631\u062f \u0645\u0646 \u0630\u0647\u0628 \u0625\u0644\u064a\u0647\u0645\u060c \u0641\u0642\u062f \u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062a\u0639\u0644\u064a\u0644 \u0630\u0644\u0643 \u0648\u0627\u0644\u062d\u0643\u0645\u0629 \u0641\u064a\u0647 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u0628\u0642\u0648\u0644\u0647: \u0645\u0646 \u0630\u0647\u0628 \u0645\u0646\u0627 \u0625\u0644\u064a\u0647\u0645 \u0641\u0623\u0628\u0639\u062f\u0647 \u0627\u0644\u0644\u0647 \u0648\u0645\u0646 \u062c\u0627\u0621\u0646\u0627 \u0645\u0646\u0647\u0645 \u0633\u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647 \u0641\u0631\u062c\u0627\u064b \u0648\u0645\u062e\u0631\u062c\u0627\u064b \u062b\u0645 \u0643\u0627\u0646 \u0643\u0645\u0627 \u0642\u0627\u0644 \ufdfa .",null)
