B.aGp=new A.a("\u0641\u0642\u0627\u0644 \u0639\u062a\u0628\u0629: \u062d\u0633\u0628\u0643\u060c \u0645\u0627 \u0639\u0646\u062f\u0643 \u063a\u064a\u0631 \u0647\u0630\u0627\u061f \u0642\u0627\u0644: \u0644\u0627 \u0641\u0631\u062c\u0639 \u0625\u0644\u0649 \u0642\u0631\u064a\u0634 \u0641\u0642\u0627\u0644\u0648\u0627: \u0645\u0627 \u0648\u0631\u0627\u0621\u0643\u061f \u0642\u0627\u0644: \u0645\u0627 \u062a\u0631\u0643\u062a \u0634\u064a\u0626\u064b\u0627 \u0623\u0631\u0649 \u0623\u0646\u0643\u0645 \u062a\u0643\u0644\u0645\u0648\u0646\u0647 \u0625\u0644\u0627 \u0643\u0644\u0645\u062a\u0647\u060c \u0642\u0627\u0644\u0648\u0627: \u0641\u0647\u0644 \u0623\u062c\u0627\u0628\u0643\u061f \u0641\u0642\u0627\u0644: \u0646\u0639\u0645 \u060c \u0648\u0641\u064a \u0631\u0648\u0627\u064a\u0629 \u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642: \u0641\u0644\u0645\u0627 \u062c\u0644\u0633 \u0625\u0644\u064a\u0647\u0645 \u0642\u0627\u0644\u0648\u0627: \u0645\u0627 \u0648\u0631\u0627\u0621\u0643 \u064a\u0627 \u0623\u0628\u0627 \u0627\u0644\u0648\u0644\u064a\u062f\u061f \u0642\u0627\u0644: \u0648\u0631\u0627\u0626\u064a \u0623\u0646\u064a \u0642\u062f \u0633\u0645\u0639\u062a \u0642\u0648\u0644\u0627\u064b \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0633\u0645\u0639\u062a \u0645\u062b\u0644\u0647 \u0642\u0637\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0647\u0648 \u0628\u0627\u0644\u0634\u0639\u0631 \u0648\u0644\u0627 \u0628\u0627\u0644\u0633\u062d\u0631 \u0648\u0644\u0627 \u0628\u0627\u0644\u0643\u0647\u0627\u0646\u0629. \u064a\u0627 \u0645\u0639\u0634\u0631 \u0642\u0631\u064a\u0634 \u0623\u0637\u064a\u0639\u0648\u0646\u064a \u0648\u0627\u062c\u0639\u0644\u0648\u0647\u0627 \u0628\u064a\u060c \u0648\u062e\u0644\u0648\u0627 \u0628\u064a\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0648\u0628\u064a\u0646 \u0645\u0627 \u0647\u0648 \u0641\u064a\u0647 \u0641\u0627\u0639\u062a\u0632\u0644\u0648\u0627\u060c \u0641\u0648\u0627\u0644\u0644\u0647 \u0644\u064a\u0643\u0648\u0646\u0646 \u0644\u0642\u0648\u0644\u0647 \u0627\u0644\u0630\u064a \u0633\u0645\u0639\u062a \u0645\u0646\u0647 \u0646\u0628\u0623 \u0639\u0638\u064a\u0645\u060c \u0641\u0625\u0646 \u062a\u0635\u0628\u0647 \u0627\u0644\u0639\u0631\u0628 \u0641\u0642\u062f \u0643\u0641\u064a\u062a\u0645\u0648\u0647 \u0628\u063a\u064a\u0631\u0643\u0645\u060c \u0648\u0625\u0646 \u064a\u0638\u0647\u0631 \u0639\u0644\u0649 \u0627\u0644\u0639\u0631\u0628 \u0641\u0645\u0644\u0643\u0647 \u0645\u0644\u0643\u0643\u0645 \u0648\u0639\u0632\u0647 \u0639\u0632\u0643\u0645\u060c \u0648\u0643\u0646\u062a\u0645 \u0623\u0633\u0639\u062f \u0627\u0644\u0646\u0627\u0633 \u0628\u0647\u060c \u0642\u0627\u0644\u0648\u0627: \u0633\u062d\u0631\u0643 \u0648\u0627\u0644\u0644\u0647 \u064a\u0627 \u0623\u0628\u0627 \u0627\u0644\u0648\u0644\u064a\u062f \u0628\u0644\u0633\u0627\u0646\u0647\u060c \u0642\u0627\u0644: \u0647\u0630\u0627 \u0631\u0623\u064a\u064a \u0641\u0627\u0635\u0646\u0639\u0648\u0627 \u0645\u0627 \u0628\u062f\u0627 \u0644\u0643\u0645.",null)
B.aIA=new A.a("\u062a\u0623\u062b\u0631 \u0639\u062a\u0628\u0629 \u0645\u0646 \u0645\u0648\u0642\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0648\u0627\u0636\u062d\u064b\u0627 \u0644\u062f\u0631\u062c\u0629 \u0623\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0623\u0642\u0633\u0645\u0648\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0642\u0628\u0644 \u0623\u0646 \u064a\u062e\u0628\u0631\u0647\u0645\u060c \u0641\u0628\u0639\u062f \u0623\u0646 \u0643\u0627\u0646 \u0627\u0644\u0639\u062f\u0648 \u064a\u0646\u0648\u064a \u0627\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0625\u0630\u0627 \u0628\u0647 \u064a\u062f\u0639\u0648 \u0644\u0639\u0643\u0633 \u0630\u0644\u0643\u060c \u0641\u064a\u0637\u0644\u0628 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0623\u0646 \u062a\u062e\u0644\u064a \u0628\u064a\u0646 \u0645\u062d\u0645\u062f \ufdfa \u0648\u0645\u0627 \u064a\u0631\u064a\u062f.",null)
B.ayH=new A.a("\u0648\u0627\u0633\u062a\u0645\u0639 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0644\u0645\u0627 \u062d\u062f\u062b \u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0628\u064a\u0646 \u0639\u062a\u0628\u0629\u060c \u0648\u0643\u064a\u0641 \u0631\u0641\u0636 \u062d\u0628\u064a\u0628\u0647\u0645 \ufdfa \u0643\u0644 \u0639\u0631\u0648\u0636\u0647 \u0627\u0644\u0645\u063a\u0631\u064a\u0629\u060c \u0641\u0643\u0627\u0646 \u0630\u0644\u0643 \u062f\u0631\u0633\u064b\u0627 \u062a\u0631\u0628\u0648\u064a\u0651\u064b\u0627 \u062e\u0627\u0644\u0637 \u0623\u062d\u0634\u0627\u0621\u0647\u0645\u060c \u062a\u0639\u0644\u0645\u0648\u0627 \u0645\u0646\u0647 \u0627\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0645\u0628\u062f\u0623\u060c \u0648\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0639\u0642\u064a\u062f\u0629\u060c \u0648\u0648\u0636\u0639 \u0627\u0644\u0645\u063a\u0631\u064a\u0627\u062a \u062a\u062d\u062a \u0623\u0642\u062f\u0627\u0645 \u0627\u0644\u062f\u0639\u0627\u0629.",null)
