B.b_t=new A.a("\u0648\u0642\u062f \u0637\u0644\u0628\u0648\u0627 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u0641\u062c\u0631 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636 \u064a\u0646\u0628\u0648\u0639\u0627 \u0623\u0648 \u062a\u0643\u0648\u0646 \u0644\u0647 \u062c\u0646\u0629 \u0623\u0648 \u064a\u0633\u0642\u0637 \u0627\u0644\u0633\u0645\u0627\u0621 \u0643\u0633\u0641\u064b\u0627 \u0623\u0648 \u064a\u0623\u062a\u064a \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0642\u0628\u064a\u0644\u0627\u064b ... \u060c \u0648\u0643\u0627\u0646\u062a \u0625\u062c\u0627\u0628\u062a\u0647 \ufdfa : \u0645\u0627 \u0628\u0647\u0630\u0627 \u0628\u0639\u062b\u062a \u0625\u0644\u064a\u0643\u0645\u060c \u0625\u0646\u0645\u0627 \u062c\u0626\u062a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u0628\u0639\u062b\u0646\u064a \u0628\u0647\u060c \u0648\u0642\u062f \u0628\u0644\u063a\u062a\u0643\u0645 \u0645\u0627 \u0623\u0631\u0633\u0644\u062a \u0628\u0647 \u0625\u0644\u064a\u0643\u0645\u060c \u0641\u0625\u0646 \u062a\u0642\u0628\u0644\u0648\u0647 \u0641\u0647\u0648 \u062d\u0638\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0625\u0646 \u062a\u0631\u062f\u0648\u0647 \u0639\u0644\u064a\u060c \u0623\u0635\u0628\u0631 \u0644\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u062d\u062a\u0649 \u064a\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646\u0643\u0645.",null)
