B.au3=new A.a("\u0627\u0633\u062a\u0645\u0631 \u0628\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0639\u0646\u0627\u064a\u0629 \u0633\u0628\u062d\u0627\u0646\u0647 \u0623\u0646 \u064a\u0645\u0634\u064a \u0648\u064a\u0628\u0630\u0644 \u0637\u0627\u0642\u062a\u0647 \u062d\u062a\u0649 \u0628\u0639\u062f \u0623\u0646 \u0623\u0635\u064a\u0628\u062a \u0631\u062c\u0644\u0647\u060c \u0648\u0643\u0623\u0646\u0647 \u0644\u0627\u064a\u0634\u0643\u0648 \u0645\u0646 \u0639\u0644\u0629 \u062d\u062a\u0649 \u0625\u0630\u0627 \u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0645\u062a\u0647 \u062a\u0645\u0627\u0645\u0627\u064b \u0648\u0623\u0635\u0628\u062d \u063a\u064a\u0631 \u0645\u062d\u062a\u0627\u062c \u0644\u0628\u0630\u0644 \u0627\u0644\u062c\u0647\u062f \u0639\u0627\u062f \u0625\u0644\u064a\u0647 \u0627\u0644\u0623\u0644\u0645\u060c \u0648\u062d\u0645\u0644\u0647 \u0623\u0635\u062d\u0627\u0628\u0647\u060c \u0641\u0644\u0645\u0627 \u062d\u062f\u0651\u062b \u0627\u0644\u0646\u0628\u064a \ufdfa \u062e\u0628\u0631\u0647 \u0642\u0627\u0644 \u0644\u0647: \u0627\u0628\u0633\u0637 \u0631\u062c\u0644\u0643\u060c \u0642\u0627\u0644 \u0641\u0628\u0633\u0637\u062a \u0631\u062c\u0644\u064a \u0641\u0645\u0633\u062d\u0647\u0627 \u0641\u0643\u0623\u0646\u0647\u0627 \u0644\u0645 \u0627\u0634\u062a\u0643\u0647\u0627 \u0642\u0637.",null)
B.aIV=new A.a("\u0625\u0646 \u0643\u0644 \u0645\u0646 \u0641\u0649 \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629 \u0643\u0627\u0646\u0648\u0627 \u0645\u0646 \u0627\u0644\u062e\u0632\u0631\u062c \u0641\u0642\u062f \u062d\u0631\u0635\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646 \u064a\u0646\u0627\u0641\u0633\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0648\u0633 \u0627\u0644\u0630\u064a\u0646 \u0642\u062a\u0644\u0648\u0627 \u0643\u0639\u0628 \u0628\u0646 \u0627\u0644\u0623\u0634\u0631\u0641 \u0641\u0642\u062f \u0643\u0627\u0646\u0648\u0627 \u0643\u0641\u0631\u0633\u064a \u0631\u0647\u0627\u0646 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0629 \u0641\u064a \u0627\u0644\u062e\u064a\u0631\u0627\u062a \u0641\u0647\u0645 \u0644\u0627\u064a\u062a\u0646\u0627\u0641\u0633\u0648\u0646 \u0639\u0644\u0649 \u0627\u063a\u062a\u0646\u0627\u0645 \u0645\u0638\u0627\u0647\u0631 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0645\u0646\u0627\u0635\u0628\u060c \u0648\u0625\u0646\u0645\u0627 \u064a\u062a\u0633\u0627\u0628\u0642\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0641\u0648\u0632 \u0628\u0645\u0631\u0636\u0627\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u062a\u064a \u0645\u0622\u0644\u0647\u0627 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0644\u0633\u0639\u0627\u062f\u0629 \u0627\u0644\u0623\u062e\u0631\u0648\u064a\u0629.",null)
