B.ata=new A.a("\u0648\u0642\u062f \u062a\u0623\u0643\u062f\u062a \u0627\u0644\u0645\u062e\u0627\u0628\u0631\u0627\u062a \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u064a\u064f\u0633\u064a\u0631 \u0628\u0646 \u0631\u0650\u0632\u064e\u0627\u0645 \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0643\u0627\u0641\u064a\u0627\u064b \u0644\u0642\u064a\u0627\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0628\u0639\u062b \u0633\u0631\u064a\u0629 \u0641\u064a \u062b\u0644\u0627\u062b\u064a\u0646 \u0631\u0627\u0643\u0628\u0627\u064b \u0639\u0644\u064a\u0647\u0645 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0631\u0648\u0627\u062d\u0629\u060c \u0648\u0641\u064a\u0647\u0645 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0646\u064a\u0633\u060c \u0641\u0623\u062a\u0648\u0647 \u0641\u0642\u0627\u0644\u0648\u0627: \u0623\u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u064a\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u064a\u0633\u062a\u0639\u0645\u0644\u0643 \u0639\u0644\u0649 \u062e\u064a\u0628\u0631\u060c \u0641\u0644\u0645 \u064a\u0632\u0627\u0644\u0648\u0627 \u0628\u0647 \u062d\u062a\u0649 \u062a\u0628\u0639\u0647\u0645 \u0641\u064a \u062b\u0644\u0627\u062b\u064a\u0646 \u0631\u062c\u0644\u0627\u064b \u0645\u0639 \u0643\u0644 \u0631\u062c\u0644 \u0645\u0646\u0647\u0645 \u0631\u062f\u064a\u0641 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0643\u0627\u0646 \u0647\u0648 \u0631\u062f\u064a\u0641 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0646\u064a\u0633 \u0639\u0644\u0649 \u0628\u0639\u064a\u0631\u0647\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0643\u0627\u0646\u0648\u0627 \u0628\u064e\u0642\u0652\u0631\u0642\u064e\u0631\u0629 \u062b\u064a\u0627\u0631 \u0639\u0644\u0649 \u0633\u062a\u0629 \u0623\u0645\u064a\u0627\u0644 \u0645\u0646 \u062e\u064a\u0628\u0631\u060c \u0646\u062f\u0645 \u0627\u0644\u064a\u0633\u064a\u0631 \u0639\u0644\u0649 \u0645\u0633\u064a\u0631\u0647 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0641\u0623\u0647\u0648\u0649 \u0628\u064a\u062f\u0647 \u0639\u0644\u0649 \u0633\u064a\u0641 \u0631\u062f\u064a\u0641\u0647 \u0627\u0628\u0646 \u0623\u0646\u064a\u0633\u060c \u0641\u0641\u0637\u0646 \u0644\u0647\u060c \u0641\u0627\u0642\u062a\u062d\u0645 \u0628\u0647\u060c \u062b\u0645 \u0636\u0631\u0628\u0647 \u0628\u0627\u0644\u0633\u064a\u0641\u060c \u0641\u0642\u0637\u0639 \u0631\u062c\u0644\u0647 \u0648\u0636\u0631\u0628\u0647 \u0627\u0644\u064a\u0633\u064a\u0631 \u0628\u0650\u0645\u0650\u062e\u0652\u0631\u064e\u0634 - \u0634\u0628\u0647 \u0627\u0644\u0645\u0642\u0631\u0639\u0629 \u064a\u0636\u0631\u0628 \u0628\u0647 - \u0641\u064a \u064a\u062f\u0647 \u0645\u0646 \u0634\u0648\u0627\u062d\u0637 \u060c \u0641\u0636\u0631\u0628 \u0628\u0647 \u0648\u062c\u0647 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0641\u062c\u0631\u062d\u0647 \u0641\u064a \u0631\u0623\u0633\u0647 \u060c \u0648\u0645\u0627\u0644 \u0643\u0644 \u0631\u062c\u0644 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0631\u062f\u064a\u0641\u0647 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0641\u0642\u062a\u0644\u0647\u060c \u0625\u0644\u0627 \u0631\u062c\u0644\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0623\u0641\u0644\u062a \u0639\u0644\u0649 \u0631\u062c\u0644\u064a\u0647\u060c \u0641\u0644\u0645\u0627 \u0642\u062f\u0645 \u0627\u0628\u0646 \u0623\u0646\u064a\u0633 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062a\u0641\u0644 \u0639\u0644\u0649 \u0634\u062c\u0646\u0647\u060c \u0641\u0644\u0645 \u062a\u0642\u062d \u0648\u0644\u0645 \u062a\u0624\u0630\u0647.",null)
