B.aQc=new A.a("\u0642\u0627\u0644 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u062e\u0637\u0628\u062a \u0641\u0627\u0637\u0645\u0629 \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644\u062a \u0645\u0648\u0644\u0627\u0629 \u0644\u064a: \u0647\u0644 \u0639\u0644\u0645\u062a \u0623\u0646 \u0641\u0627\u0637\u0645\u0629 \u0642\u062f \u062e\u0637\u0628\u062a \u0627\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u061f \u0642\u0644\u062a : \u0644\u0627 \u060c \u0642\u0627\u0644\u062a: \u0641\u0642\u062f \u062e\u0637\u0628\u062a \u0641\u0645\u0627 \u064a\u0645\u0646\u0639\u0643 \u0623\u0646 \u062a\u0623\u062a\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a\u0632\u0648\u062c\u0643\u060c \u0641\u0642\u0644\u062a: \u0648\u0639\u0646\u062f\u064a \u0634\u064a\u0621 \u0623\u062a\u0632\u0648\u062c \u0628\u0647! \u0641\u0642\u0627\u0644\u062a: \u0625\u0646\u0643 \u0625\u0646 \u062c\u0626\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0632\u0648\u062c\u0643.",null)
B.aBR=new A.a("\u0642\u0627\u0644: \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0632\u0644\u062a \u062a\u0631\u062c\u064a\u0646\u064a \u062d\u062a\u0649 \u062f\u062e\u0644\u062a \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0644\u0645\u0627 \u0623\u0646 \u0642\u0639\u062f\u062a \u0628\u064a\u0646 \u064a\u062f\u064a\u0647 \u0623\u0641\u062d\u0645\u062a \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0627\u0633\u062a\u0637\u0639\u062a \u0623\u0646 \u0623\u062a\u0643\u0644\u0645 \u062c\u0644\u0627\u0644\u0629 \u0648\u0647\u064a\u0628\u0629.",null)
B.avu=new A.a("\u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0645\u0627\u062c\u0627\u0621 \u0628\u0643\u061f \u0623\u0644\u0643 \u062d\u0627\u062c\u0629\u061f \u0641\u0633\u0643\u062a \u0641\u0642\u0627\u0644: \u0644\u0639\u0644\u0643 \u062c\u0626\u062a \u062a\u062e\u0637\u0628 \u0641\u0627\u0637\u0645\u0629\u061f \u0641\u0642\u0644\u062a: \u0646\u0639\u0645 \u0641\u0642\u0627\u0644: \u0648\u0647\u0644 \u0639\u0646\u062f\u0643 \u0645\u0646 \u0634\u064a\u0621 \u0633\u062a\u062d\u0644\u0647\u0627 \u0628\u0647\u061f \u0641\u0642\u0644\u062a: \u0644\u0627 \u0648\u0627\u0644\u0644\u0647 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0642\u0627\u0644: \u0645\u0627\u0641\u0639\u0644\u062a \u062f\u0631\u0639 \u0633\u0644\u062d\u062a\u0643\u0647\u0627 \u061f \u0641\u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633 \u0639\u0644\u064a \u0628\u064a\u062f\u0647 \u0625\u0646\u0647\u0627 \u0644\u062d\u0637\u0645\u064a\u0629 \u0645\u0627\u0642\u064a\u0645\u062a\u0647\u0627 \u0623\u0631\u0628\u0639\u0629 \u062f\u0631\u0627\u0647\u0645 \u0641\u0642\u0644\u062a: \u0639\u0646\u062f\u064a\u060c \u0641\u0642\u0627\u0644: \u0642\u062f \u0632\u0648\u062c\u062a\u0643\u0647\u0627 \u0641\u0627\u0628\u0639\u062b \u0625\u0644\u064a\u0647\u0627 \u0628\u0647\u0627 \u0641\u0627\u0633\u062a\u062d\u0644\u0647\u0627 \u0628\u0647\u0627 \u0641\u0625\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0644\u0635\u062f\u0627\u0642 \u0641\u0627\u0637\u0645\u0629 \u0628\u0646\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0642\u062f \u062c\u0647\u0632 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0627\u0637\u0645\u0629 \u0641\u064a \u062e\u0645\u064a\u0644 -\u0627\u0644\u0642\u0637\u064a\u0641\u0629- \u0648\u0642\u0631\u0628\u0629 \u0648\u0648\u0633\u0627\u062f\u0629 \u0623\u062f\u0645 -\u0627\u0644\u062c\u0644\u062f- \u062d\u0634\u0648\u0647\u0627 \u0625\u0630\u062e\u0631.",null)
