B.aL7=new A.a("\u0648\u0639\u0646 \u0627\u0628\u0646 \u0639\u0645\u0631 \u0642\u0627\u0644: \u0644\u0645\u0627 \u0623\u0633\u0644\u0645 \u0639\u0645\u0631 \u0642\u0627\u0644: \u0623\u064a\u0651\u064f \u0642\u0631\u064a\u0634 \u0623\u0646\u0642\u0644 \u0644\u0644\u062d\u062f\u064a\u062b\u061f \u0642\u064a\u0644 \u0644\u0647: \u062c\u0645\u064a\u0644 \u0628\u0646 \u0645\u0639\u0645\u0631 \u0627\u0644\u062c\u064f\u0645\u062d\u064a\u060c \u0642\u0627\u0644: \u0641\u063a\u062f\u0627 \u0639\u0644\u064a\u0647\u060c \u0642\u0627\u0644 \u0639\u0628\u062f \u0627\u0644\u0644\u0647: \u0648\u063a\u062f\u0648\u062a \u0645\u0639\u0647 \u0623\u062a\u0628\u0639 \u0623\u062b\u0631\u0647\u060c \u0648\u0623\u0646\u0638\u0631 \u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 \u062d\u062a\u0649 \u062c\u0627\u0621\u0647 \u0641\u0642\u0627\u0644 \u0644\u0647: \u0623\u0639\u0644\u0645\u062a \u064a\u0627 \u062c\u0645\u064a\u0644 \u0623\u0646\u064a \u0623\u0633\u0644\u0645\u062a \u0648\u062f\u062e\u0644\u062a \u0641\u064a \u062f\u064a\u0646 \u0645\u062d\u0645\u062f\u061f \u0642\u0627\u0644: \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0631\u0627\u062c\u0639\u0647 \u062d\u062a\u0649 \u0642\u0627\u0645 \u064a\u062c\u0631 \u0631\u062f\u0627\u0621\u0647 \u0648\u062a\u0628\u0639\u0647 \u0639\u0645\u0631\u060c \u0648\u0627\u062a\u0628\u0639\u062a \u0623\u0628\u064a \u062d\u062a\u0649 \u0625\u0630\u0627 \u0642\u0627\u0645 \u0639\u0644\u0649 \u0628\u0627\u0628 \u0627\u0644\u0645\u0633\u062c\u062f \u0635\u0631\u062e \u0628\u0623\u0639\u0644\u0649 \u0635\u0648\u062a\u0647: \u064a\u0627 \u0645\u0639\u0634\u0631 \u0642\u0631\u064a\u0634 \u0648\u0647\u0645 \u0641\u064a \u0623\u0646\u062f\u064a\u062a\u0647\u0645 \u062d\u0648\u0644 \u0627\u0644\u0643\u0639\u0628\u0629 - \u0623\u0644\u0627 \u0625\u0646 \u0627\u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0642\u062f \u0635\u0628\u0623  -\u062e\u0631\u062c \u0645\u0646 \u062f\u064a\u0646 \u0625\u0644\u0649 \u062f\u064a\u0646 \u0622\u062e\u0631-  \u0642\u0627\u0644: \u064a\u0642\u0648\u0644 \u0639\u0645\u0631 \u0645\u0646 \u062e\u0644\u0641\u0647: \u0643\u0630\u0628\u060c \u0648\u0644\u0643\u0646\u064a \u0623\u0633\u0644\u0645\u062a\u060c \u0648\u0634\u0647\u062f\u062a \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c",null)
B.aK1=new A.a("\u0648\u062b\u0627\u0631\u0648\u0627 \u0625\u0644\u064a\u0647 \u0641\u0645\u0627 \u0628\u0631\u062d \u064a\u0642\u0627\u062a\u0644\u0647\u0645 \u0648\u064a\u0642\u0627\u062a\u0644\u0648\u0646\u0647 \u062d\u062a\u0649 \u0642\u0627\u0645\u062a \u0627\u0644\u0634\u0645\u0633 \u0639\u0644\u0649 \u0631\u0624\u0648\u0633\u0647\u0645 \u0648\u064e\u0637\u064e\u0644\u0650\u062d  \u0641\u0642\u0639\u062f\u060c \u0648\u0642\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0631\u0623\u0633\u0647 \u0648\u0647\u0648 \u064a\u0642\u0648\u0644: \u0627\u0641\u0639\u0644\u0648\u0627 \u0645\u0627 \u0628\u062f\u0627 \u0644\u0643\u0645 \u0641\u0623\u062d\u0644\u0641 \u0628\u0627\u0644\u0644\u0647 \u0623\u0646 \u0644\u0648 \u0643\u0646\u0627 \u062b\u0644\u0627\u062b\u0645\u0627\u0626\u0629 \u0644\u0642\u062f \u062a\u0631\u0643\u0646\u0627\u0647\u0627 \u0623\u0648 \u062a\u0631\u0643\u062a\u0645\u0648\u0647\u0627 \u0644\u0646\u0627. ",null)
B.avc=new A.a("\u0644\u0642\u062f \u0623\u0635\u0628\u062d \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0625\u0630\u064b\u0627 \u0641\u064a \u0648\u0636\u0639 \u063a\u064a\u0631 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u0648\u0627 \u0641\u064a\u0647 \u0642\u0628\u0644 \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0641\u0642\u062f \u0627\u0645\u062a\u0646\u0639\u0648\u0627 \u0628\u062d\u0645\u0632\u0629 \u0648\u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627\u060c \u0648\u0627\u0633\u062a\u0637\u0627\u0639\u0648\u0627 \u0623\u0646 \u064a\u0635\u0644\u0648\u0627 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u0628\u0639\u062f \u0623\u0646 \u0643\u0627\u0646\u0648\u0627 \u0644\u0627 \u064a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0648\u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u0628\u064a\u062a \u0627\u0644\u0623\u0631\u0642\u0645 \u0628\u0646 \u0623\u0628\u064a \u0627\u0644\u0623\u0631\u0642\u0645 \u0645\u062c\u0627\u0647\u0631\u064a\u0646 \u062d\u062a\u0649 \u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0643\u0641\u062a \u0642\u0631\u064a\u0634 \u0639\u0646 \u0625\u064a\u0630\u0627\u0626\u0647\u0645 \u0628\u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u0648\u062d\u0634\u064a\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u0639\u0630\u0628\u0647\u0645 \u0628\u0647\u0627 \u0642\u0628\u0644 \u0630\u0644\u0643.",null)
