B.aWW=new A.a("\u0623\u0645\u0627 \u0627\u0644\u0641\u0631\u0627\u0634 \u0627\u0644\u0630\u064a \u064a\u0623\u0648\u064a \u0625\u0644\u064a\u0647 \u0647\u0630\u0627 \u0627\u0644\u0646\u0628\u064a \u0639\u0644\u064a\u0647 \u0623\u0641\u0636\u0644 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0623\u062a\u0645 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0641\u0647\u0648 \u0639\u0628\u0627\u0631\u0629 \u0639\u0646 \u0631\u0645\u0627\u0644 \u062d\u0635\u064a\u0631 \u0644\u064a\u0633 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646\u0647 \u0641\u0631\u0627\u0634 \u0642\u062f \u0623\u062b\u0631 \u0627\u0644\u0631\u0645\u0627\u0644 \u0628\u062c\u0646\u0628\u0647\u060c \u0648\u0648\u0633\u0627\u062f\u062a\u0647 \u0645\u0646 \u0623\u062f\u0645 \u062d\u0634\u0648\u0647\u0627 \u0644\u064a\u0641\u060c \u0641\u0642\u062f \u0643\u0627\u0646\u062a \u0645\u0639\u064a\u0634\u062a\u0647 \ufdfa \u062a\u062f\u0644 \u0639\u0644\u0649 \u0627\u0644\u0634\u062f\u0629\u060c \u0641\u0639\u0646 \u0623\u0646\u0633 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0645\u0627 \u0623\u0639\u0644\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0631\u0623\u0649 \u0631\u063a\u064a\u0641\u0627\u064b \u0645\u0631\u0642\u0642\u0627\u064b \u062d\u062a\u0649 \u0644\u062d\u0642 \u0628\u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u0631\u0623\u0649 \u0634\u0627\u0629 \u0633\u0645\u064a\u0637\u0627\u064b -\u0627\u0644\u0630\u064a \u0623\u0632\u064a\u0644 \u0634\u0639\u0631\u0647 \u0628\u0627\u0644\u0645\u0627\u0621 \u0627\u0644\u0645\u0633\u062e\u0646 \u0648\u0634\u0648\u064a- \u0628\u0639\u064a\u0646\u0647 \u0642\u0637\u060c \u0648\u0639\u0646 \u0639\u0627\u0626\u0634\u0629 \u0642\u0627\u0644\u062a: \u0625\u0646 \u0643\u0646\u0627 \u0644\u0646\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u0647\u0644\u0627\u0644 \u062b\u0644\u0627\u062b\u0629 \u0623\u0647\u0644\u0629 \u0641\u064a \u0634\u0647\u0631\u064a\u0646 \u0648\u0645\u0627 \u0623\u0648\u0642\u062f\u062a \u0641\u064a \u0623\u0628\u064a\u0627\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0646\u0627\u0631\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0627 \u0639\u0631\u0648\u0629 \u0628\u0646 \u0627\u0644\u0632\u0628\u064a\u0631: \u0645\u0627\u0643\u0627\u0646 \u064a\u0639\u064a\u0634\u0643\u0645\u061f \u0642\u0627\u0644\u062a: \u0627\u0644\u0623\u0633\u0648\u062f\u0627\u0646: \u0627\u0644\u062a\u0645\u0631 \u0648\u0627\u0644\u0645\u0627\u0621 \u0647\u0630\u0627 \u0648\u0642\u062f \u0641\u062a\u062d \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0639\u062f \u062e\u064a\u0628\u0631 \u0648\u0641\u062a\u062d \u0645\u0643\u0629 \u0648\u063a\u0632\u0648\u0629 \u062a\u0628\u0648\u0643.",null)
