B.aPl=new A.a("\u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u062d\u062c \u0623\u062d\u062f \u0627\u0644\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u062e\u0645\u0633\u0629 \u0648\u0642\u062f \u0641\u0631\u0636 \u0641\u064a \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0639\u0627\u0634\u0631 \u0648\u0647\u0630\u0627 \u0645\u0627\u0630\u0647\u0628 \u0625\u0644\u064a\u0647 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645 \u0648\u0627\u0633\u062a\u062f\u0644 \u0628\u0623\u062f\u0644\u0629 \u0642\u0648\u064a\u0629 \u0648\u0647\u0648 \u0627\u0644\u0644\u0627\u0626\u0642 \u0628\u0647\u062f\u064a\u0647 \ufdfa \u0641\u064a \u0639\u062f\u0645 \u062a\u0623\u062e\u064a\u0631 \u0645\u0627\u0647\u0648 \u0641\u0631\u0636 \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0642\u0648\u0644: \u0648\u064e\u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u062d\u0650\u062c\u0651\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u0627 - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646 \u060c \u0648\u0642\u062f \u0646\u0632\u0644\u062a \u0639\u0627\u0645 \u0627\u0644\u0648\u0641\u0648\u062f \u0623\u0648\u0627\u062e\u0631 \u0633\u0646\u0629 \u062a\u0633\u0639.",null)
